"""Deterministic stand-in physics shared by all mechanisms (updated in simulation_periodic)."""

from dataclasses import dataclass


@dataclass
class Plant:
    elevator_pos: float = 0.0     # meters
    elevator_volts: float = 0.0
    elevator_limit: bool = True   # bottom limit switch
    arm_angle: float = 90.0       # degrees, 90 = stowed vertical
    arm_volts: float = 0.0
    roller_volts: float = 0.0
